mapper.sql:
RECURSIVE recv(symbol_id) AS (


        SELECT s.symbol_id FROM analysis_symbol s
         WHERE s.revision_id = #{revisionId}
           AND s.fqn IN #{t}
        UNION
        SELECT x.from_id FROM analysis_relation x
         WHERE x.revision_id = #{revisionId}
           AND x.relation_type IN ('EXTENDS', 'IMPLEMENTS')
           AND x.to_external IN #{t}
        UNION
        SELECT x.from_id FROM analysis_relation x
          JOIN recv ON x.to_id = recv.symbol_id
         WHERE x.revision_id = #{revisionId}
           AND x.relation_type IN ('EXTENDS', 'IMPLEMENTS')

    SELECT NULL::varchar WHERE FALSE

)

AND (
OR (r.ref_kind = 'CALL' AND r.name IN #{name}
AND (EXISTS ( SELECT 1 FROM analysis_relation c LEFT JOIN analysis_method tm ON tm.revision_id = c.revision_id AND tm.method_id = c.to_id WHERE c.revision_id = r.revision_id AND c.from_id = r.from_id AND c.file_id = r.file_id AND c.line_start = r.line_start AND c.relation_type = 'CALLS' AND ((tm.name = r.name AND tm.owner_symbol_id IN (SELECT symbol_id FROM recv))
OR c.to_external = #{t} || '.' || r.name OR c.to_external LIKE #{t} || '.' || r.name || '(%' )) OR ((r.scope_text IS NULL OR r.scope_text IN ('this', 'super')) AND caller.owner_symbol_id IN (SELECT symbol_id FROM recv))) )
OR (r.ref_kind = 'CREATE' AND r.name IN #{name})
)

mapper.select:
SELECT symbol_id AS "symbolId", fqn AS "fqn", kind AS "kind", is_abstract AS "isAbstract", layer AS "layer"
  FROM analysis_symbol
 WHERE revision_id = #{revisionId}
   AND symbol_id IN #{id}

SELECT file_id AS "fileId", path AS "path", encoding AS "encoding"
  FROM analysis_file
 WHERE revision_id = #{revisionId}
   AND file_type = #{fileType}
   AND parse_status <> 'SKIPPED'
 ORDER BY path

SELECT file_id AS "fileId", path AS "path", encoding AS "encoding"
  FROM analysis_file
 WHERE revision_id = #{revisionId}
   AND language = #{language}
   AND parse_status <> 'SKIPPED'
 ORDER BY path

mapper.insert:
INSERT INTO analysis_endpoint (revision_id, endpoint_type, symbol_id, method_id, properties_json, file_id, line_start) SELECT DISTINCT ON (m.method_id) #{revisionId}, #{endpointType}, m.owner_symbol_id, m.method_id , jsonb_build_object('super', COALESCE(r.to_external, t.fqn)) , m.file_id, m.line_start FROM analysis_relation r LEFT JOIN analysis_symbol t ON t.revision_id = r.revision_id AND t.symbol_id = r.to_id JOIN analysis_method m ON m.revision_id = r.revision_id AND m.owner_symbol_id = r.from_id AND NOT m.is_synthetic AND NOT m.is_constructor WHERE r.revision_id = #{revisionId} AND r.relation_type IN ('EXTENDS', 'IMPLEMENTS') AND COALESCE(r.to_external, t.fqn) IN #{name}
AND m.name IN #{name}
AND m.name ~ #{methodPattern}
AND m.param_count = #{paramCount} AND NOT EXISTS ( SELECT 1 FROM analysis_endpoint e WHERE e.revision_id = m.revision_id AND e.endpoint_type = #{endpointType} AND e.method_id = m.method_id) ORDER BY m.method_id, r.relation_id

mapper.select:
SELECT method_id AS "methodId", name AS "name", line_start AS "lineStart"
  FROM analysis_method
 WHERE revision_id = #{revisionId}
   AND owner_symbol_id = #{symbolId}
   AND name IN
    #{name}
   AND NOT is_synthetic
   AND NOT is_constructor
 ORDER BY line_start

mapper.update:
UPDATE analysis_symbol
   SET layer = #{layer}, layer_confidence = 'HIGH'
 WHERE revision_id = #{revisionId}
   AND symbol_id = #{symbolId}
   AND layer IS NULL

mapper.delete:
DELETE FROM analysis_relation
 WHERE revision_id = #{revisionId}
   AND relation_type IN ('RENDERS', 'REQUESTS', 'INCLUDES')

mapper.select:
SELECT file_id AS "fileId", path AS "path", encoding AS "encoding"
  FROM analysis_file
 WHERE revision_id = #{revisionId}
   AND language = #{language}
   AND parse_status <> 'SKIPPED'
   AND file_id > #{afterId}
 ORDER BY file_id
 LIMIT #{limit}

SELECT file_id AS "fileId", path AS "path", encoding AS "encoding"
  FROM analysis_file
 WHERE revision_id = #{revisionId}
   AND language IN
    #{language}
   AND parse_status <> 'SKIPPED'
   AND file_id > #{afterId}
 ORDER BY file_id
 LIMIT #{limit}

SELECT file_id AS "fileId", path AS "path", encoding AS "encoding", file_type AS "fileType"
  FROM analysis_file
 WHERE revision_id = #{revisionId}
   AND file_type IN
    #{fileType}
   AND parse_status <> 'SKIPPED'
   AND file_id > #{afterId}
 ORDER BY file_id
 LIMIT #{limit}

mapper.sql:
 WHERE e.revision_id = #{revisionId}
AND e.endpoint_type = #{endpointType}
AND e.path LIKE '%' || #{path} || '%'

mapper.select:
SELECT f.file_id AS "fileId", f.path AS "path", f.encoding AS "encoding", f.checksum AS "checksum"
  FROM analysis_file f
 WHERE f.revision_id = #{revisionId}
   AND f.file_id > #{afterId}
   AND EXISTS (SELECT 1 FROM analysis_method m
                WHERE m.revision_id = #{revisionId} AND m.file_id = f.file_id
                  AND NOT m.is_synthetic AND m.line_start IS NOT NULL)
 ORDER BY f.file_id
 LIMIT #{limit}
